  {
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "mainEntity": [
      {
        "@type": "Question",
        "name": "What is ADAS and autonomous vehicle data collection?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "It's the capture of synchronized camera, LiDAR, radar, GNSS, and vehicle data from real driving, plus in-cabin sensing, used to train and validate perception, planning, and driver-monitoring systems."
        }
      },
      {
        "@type": "Question",
        "name": "How much driving data does an ADAS program need?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Total miles matter less than coverage. We map the operational design domain into cells, such as road type, weather, lighting, and road users, and collect to fill the cells with too little data."
        }
      },
      {
        "@type": "Question",
        "name": "How do you collect rare or dangerous driving scenarios?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Through scenario-targeted drives in the conditions where they occur, and controlled track staging with soft targets for high-risk variants, all tagged for training and held-out evaluation."
        }
      },
      {
        "@type": "Question",
        "name": "Do you collect in-cabin driver monitoring data?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Yes, with consented participants across drivers, lighting, eyewear, and seating positions, under a privacy design agreed before capture."
        }
      },
      {
        "@type": "Question",
        "name": "What calibration records come with automotive data?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Each drive includes camera intrinsics, camera-LiDAR extrinsics, time synchronization records, and ego pose, so fusion labels and validation results can be traced."
        }
      },
      {
        "@type": "Question",
        "name": "Do you support autonomous trucking too?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Yes. Heavy-duty trucking has its own range, braking, and hub-to-hub needs; see our trucking industry page."
        }
      }
    ]
  }
